/**
 * Signals in message MC_DriveCommand.
 *
 * Fixed WS22 classic CAN: little-endian IEEE-754 floats; vendor units and wire layout are exempt from team scaling. All WS22 frames have eight data bytes.
 *
 * All signal values are as on the CAN bus.
 */
struct motor_can_raw_mc_drive_command_t {
    /**
     * Signed velocity setpoint; reverse requires negative rpm. Operational limits are controller settings, not wire limits.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint32_t mc_motor_velocity_setpoint;

    /**
     * Vendor current fraction: 0.0 to 1.0, never 0 to 100.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint32_t mc_motor_current_setpoint;
};

